import{_ as n,l as o,o as e,c as l,v as i,p as s,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"从欧拉到动态 IS","description":"","frontmatter":{"title":"从欧拉到动态 IS","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/dynamic-is.md","filePath":"econ/dynamic-is.md","lastUpdated":1789023840000}'),h={name:"econ/dynamic-is.md"};function _(m,a,E,S,I,b){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=i('<h1 id="从欧拉到动态-is" tabindex="-1">从欧拉到动态 IS <a class="header-anchor" href="#从欧拉到动态-is" aria-label="Permalink to &quot;从欧拉到动态 IS&quot;">​</a></h1><div class="epigraph"><p>商品市场出清之后，欧拉不再只是家庭的一阶条件，而是一条把缺口接到实际利率相对 $r^n$ 之差的前瞻 IS。</p><footer>—— Woodford, Interest and Prices, 2003</footer></div><p><a href="/econ/hybrid-nkpc">上一课</a>（混合 NKPC）。把供给写成 NKPC。需求侧的欧拉在<a href="/econ/consumption-euler">跨期消费</a>已经出现，本课不再从 Ramsey 重推。缺口是：对数线性、加上资源约束，把它收成与 NKPC 联立的动态 IS。有了这两条，利率规则才有一个可解的系统。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>欧拉说：实际利率相对时间偏好越高，消费越往后推。宏观要的不是家庭自己的 \\(c\\)，而是产出缺口如何对政策利率反应。若无投资、无政府，商品市场 \\(y_t=c_t\\)，对数线性后当期缺口等于预期下期缺口减去跨期替代弹性乘以实际利率相对自然率的偏离。缺口是把「欧拉成立」写成可与 Phillips 配对的 IS，而不是再讲一遍边际效用。</p><p><span class="marginnote">自然实际利率 \\(r^n_t\\) 是灵活价格均衡下的实际利率，下一课会把它叫 \\(r^*\\)。本课先把它当 IS 的漂移项：政策盯的是 \\(i-\\mathbb{E}\\pi\\) 对 \\(r^n\\) 的差，不是 \\(i\\) 的绝对水平。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对<a href="/econ/consumption-euler">欧拉</a>在稳态附近对数线性，并用 \\(y=c\\) 替换，得到 Woodford 的跨期 IS</p> \\[\\tilde{y}_t=\\mathbb{E}_t\\tilde{y}_{t+1}-\\sigma\\bigl(i_t-\\mathbb{E}_t\\pi_{t+1}-r^n_t\\bigr). \\]<p>\\(\\sigma\\) 是跨期替代弹性。\\(r^n_t\\) 随偏好、技术、政府购买的灵活价格路径而动；它不是政策选的。有投资或 \\(G\\) 时，式子多若干预期项，形状不变：需求向前看，实际利率相对 \\(r^n\\) 越高，当前 \\(\\tilde{y}\\) 越低。</p>',10)),(e(),s(c,null,{default:t(()=>[p(r,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20EU%5B%22%E6%B6%88%E8%B4%B9%E6%AC%A7%E6%8B%89%22%5D%20--%3E%20LIS%5B%22%E5%AF%B9%E6%95%B0%E7%BA%BF%E6%80%A7%22%5D%0A%20%20LIS%20--%3E%20DIS%5B%22%E5%8A%A8%E6%80%81%20IS%EF%BC%9A%E1%BB%B9%20%E5%AF%B9%20r%E2%88%92r%E2%81%BF%22%5D%0A%20%20NKPC%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%20NKPC%22%5D%20--%3E%20SYS%5B%22%E8%81%94%E7%AB%8B%22%5D%0A%20%20DIS%20--%3E%20SYS%0A%20%20I%5B%22%E5%90%8D%E4%B9%89%20i%22%5D%20--%3E%20RI%5B%22i%E2%88%92E%CF%80%22%5D%0A%20%20RI%20--%3E%20DIS%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>三方程的第三块是后课的利率规则。本课只关闭需求：给定实际利率路径，IS 给出 \\(\\tilde{y}\\) 路径；NKPC 再给出 \\(\\pi\\)。Hicks 的 IS 是 \\(Y\\) 对 \\(i\\) 的同期向下倾斜；动态 IS 的斜率仍在，但截距是 \\(\\mathbb{E}\\tilde{y}_{t+1}\\) 与 \\(r^n\\)。</p><h3 id="不是把-请回来" tabindex="-1">不是把 \\(C=cY\\) 请回来 <a class="header-anchor" href="#不是把-请回来" aria-label="Permalink to &quot;不是把 $C=cY$ 请回来&quot;">​</a></h3><p>静态消费函数把可预测收入写成大正的 MPC。欧拉已经拒绝这一点。动态 IS 里当期 \\(Y\\) 仍通过资源约束出现，通道是财富与预期路径。流动性约束家庭会让一部分需求重新变「当期」，那是摩擦，要声明，不能默默退回乘数菜单。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>央行提高 \\(i\\)，若 \\(\\mathbb{E}\\pi\\) 未一对一跟上，实际利率高于 \\(r^n\\)，欧拉要求当前需求下降，\\(\\tilde{y}\\) 下降，再经 NKPC 压 \\(\\pi\\)。预期下期缺口若也被压低，今天的 IS 进一步左移——前瞻使规则的<strong>未来</strong>一段进入当前需求。这与数量论的长期中性不冲突：稳态 \\(\\tilde{y}=0\\)，\\(i=\\pi^*+r^n\\)。</p><p>\\(r^n\\) 自己会动。正的技术冲击在灵活价格下抬自然产出，也可能改 \\(r^n\\)；把观察到的 \\(y\\) 下降全写成需求不足，会把自然率变动误读成缺口。RBC 对照正是这条极限。<a href="/econ/divine-coincidence">神圣巧合</a>会再问：稳 \\(\\pi\\) 是否已经把这条 IS 上的缺口一起关掉；本课只把需求侧方程交给三方程。</p><p>政府购买进入资源约束时，动态 IS 的截距含 \\(G\\) 的灵活价格路径：那是 \\(r^n\\) 的一部分，不是把 Hicks 的乘数请回结构。李嘉图下一次总付减税不移动 IS；受约束家庭会。声明摩擦，才能谈乘数。</p><p><span class="marginnote">\\(\\sigma\\) 小则同样利率偏离对应更小的缺口反应。估计 \\(\\sigma\\) 不是本课。宏观主干只用无风险欧拉；股票溢价留给资产定价，以免吞并量化栏。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把金融摩擦写进 IS，不讨论零下限——那是工具卡住之后的课。开放经济下 IS 还含 \\(q\\) 与外国需求，蒙代尔再打开。也不要把限价簿的微观利率当政策 \\(i\\)。Hall 的随机游走是欧拉的可观测特例；动态 IS 是同一欧拉的宏观写法，不在此重估消费过度敏感。</p><p>后课默认：需求侧是前瞻 IS，政策利率通过 \\(i-\\mathbb{E}\\pi-r^n\\) 进缺口。下一课对照：若价格灵活，\\(\\tilde{y}\\) 消失，周期还剩自然产出自己的波动。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>动态 IS 是欧拉加商品出清的对数线性，不是静态 \\(C(Y)\\)。</li><li>\\(\\tilde{y}_t=\\mathbb{E}_t\\tilde{y}_{t+1}-\\sigma(i_t-\\mathbb{E}_t\\pi_{t+1}-r^n_t)\\)。</li><li>政策盯的是实际利率对 \\(r^n\\) 的偏离。</li><li>前瞻使未来路径进入当前需求。</li><li>流动性约束让一部分需求重新变当期，必须声明摩擦。</li><li>出处：Woodford, <em>Interest and Prices</em>。</li></ul>',13))])}const f=n(h,[["render",_]]);export{u as __pageData,f as default};
